(function(){var match=(window.location.pathname||'').match(/^\/([^\/]+)\/manage\/?$/);var slug=match?match[1]:'';var form=document.querySelector('[data-fm-spotlight-form]');var status=document.querySelector('[data-fm-spotlight-status]');var removeBtn=document.querySelector('[data-fm-spotlight-remove]');function setStatus(msg,kind){if(!status)return;status.textContent=msg;status.removeAttribute('hidden');status.dataset.kind=kind||'info';}
function clearStatus(){if(!status)return;status.setAttribute('hidden','');status.textContent='';delete status.dataset.kind;}
function submit(){if(!slug||!form)return;var data={kind:(form.querySelector('#spotlight-kind')||{}).value||'url',ref_id:'',text:(form.querySelector('#spotlight-text')||{}).value||'',url:(form.querySelector('#spotlight-url')||{}).value||'',emoji:(form.querySelector('#spotlight-emoji')||{}).value||'★'};setStatus('Saving…','info');fetch('/'+slug+'/manage/spotlight',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}).then(function(r){return r.json().catch(function(){return{};});}).then(function(j){if(j&&j.ok){setStatus('Saved ✓','ok');setTimeout(function(){window.location.reload();},600);}else{setStatus('Save failed. Try again.','err');}}).catch(function(){setStatus('Save failed. Try again.','err');});}
if(form){form.addEventListener('submit',function(e){e.preventDefault();submit();});}
if(removeBtn){removeBtn.addEventListener('click',function(){if(!slug)return;if(!window.confirm('Remove your Spotlight?'))return;fetch('/'+slug+'/manage/spotlight',{method:'DELETE',credentials:'same-origin'}).then(function(r){return r.json().catch(function(){return{};});}).then(function(j){if(j&&j.ok)window.location.reload();else setStatus('Could not remove. Try again.','err');}).catch(function(){setStatus('Could not remove. Try again.','err');});});}})();